WITH with_windows AS (SELECT id, merchant, is_flagged, MIN(amount) OVER (PARTITION BY account_id, txn_type) AS account_id_min_amount, ROUND(amount / SUM(amount) OVER (PARTITION BY account_id), 4) AS amount_share, NTILE(5) OVER w_running AS amount_bucket FROM transactions WINDOW w_running AS (PARTITION BY account_id ORDER BY amount, id)), scored AS (SELECT *, LEAD(amount_share, 1) OVER (PARTITION BY merchant ORDER BY account_id_min_amount, id) AS next_amount_share, SUM(amount_bucket) OVER (PARTITION BY merchant) AS merchant_sum_amount_bucket, LEAD(amount_share, 1) OVER (PARTITION BY merchant ORDER BY amount_share, id) AS next_amount_share_2 FROM with_windows WHERE merchant != 'Grab'), base AS (SELECT *, ROUND(amount_share * 0.9, 2) AS adjusted_amount_share FROM scored WHERE amount_bucket != 3 AND merchant IS NOT NULL), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY merchant ORDER BY next_amount_share_2 DESC, id) AS row_num FROM base) x WHERE row_num = 1) SELECT id, merchant, is_flagged, account_id_min_amount, amount_share, next_amount_share, merchant_sum_amount_bucket, next_amount_share_2 FROM latest ORDER BY amount_share DESC, next_amount_share DESC;
